class BSTIterator {
private:
    vector<TreeNode*> st;
    void pushAllLeft(TreeNode* node) {
        while (node) {
            st.push_back(node);
            node = node->left;
        }
    }
public:
    BSTIterator(TreeNode* root) {
        pushAllLeft(root);
    }
    int next() {
        TreeNode* top = st.back();
        st.pop_back();
        if (top->right) pushAllLeft(top->right);
        return top->val;
    }
    bool hasNext() {
        return !st.empty();
    }
};

class BSTIterator {
    private Deque<TreeNode> stack = new ArrayDeque<>();
    private void pushAllLeft(TreeNode node) {
        while (node != null) {
            stack.push(node);
            node = node.left;
        }
    }
    public BSTIterator(TreeNode root) {
        pushAllLeft(root);
    }
    public int next() {
        TreeNode top = stack.pop();
        if (top.right != null) pushAllLeft(top.right);
        return top.val;
    }
    public boolean hasNext() {
        return !stack.isEmpty();
    }
}

var BSTIterator = function(root) {
    this.stack = [];
    this._pushAllLeft(root);
};

BSTIterator.prototype._pushAllLeft = function(node) {
    while (node) {
        this.stack.push(node);
        node = node.left;
    }
};

BSTIterator.prototype.next = function() {
    const top = this.stack.pop();
    if (top.right) this._pushAllLeft(top.right);
    return top.val;
};

BSTIterator.prototype.hasNext = function() {
    return this.stack.length > 0;
};
